package br.com.lealinfo.vidraceiro;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Capture-only emulator instrumentation. Never compiled into the delivered APK. */
public class StaffGuideCaptureInstrumentation extends Instrumentation {
 MainActivity a;interface Op{void run()throws Exception;}void ui(Op task){final Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable x){error[0]=x;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{a.sync.close();a.access.activate();a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);});Thread.sleep(250);
 ui(()->{View root=a.root;int w=root.getWidth(),h=root.getHeight();if(w<200||h<200)throw new Exception("Capture not laid out");Bitmap image=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));File out=getContext().getExternalFilesDir(null);if(!out.exists())out.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(out,"step-5.png"))){image.compress(Bitmap.CompressFormat.PNG,100,f);}image.recycle();ArrayList<EditText> inputs=new ArrayList<>();for(int i=0;i<a.root.getChildCount();i++)if(a.root.getChildAt(i) instanceof EditText)inputs.add((EditText)a.root.getChildAt(i));if(inputs.size()!=4)throw new Exception("Expected actual enrollment fields");View code=inputs.get(1);JSONObject meta=new JSONObject().put("5",new JSONObject().put("rect",new JSONArray().put((double)code.getLeft()/w).put((double)code.getTop()/h).put((double)code.getWidth()/w).put((double)code.getHeight()/h)).put("source","Actual Android QA enrollment screen; empty fields; capture-only instrumentation"));try(FileOutputStream f=new FileOutputStream(new File(out,"android-photo.json"))){f.write(meta.toString().getBytes("UTF-8"));}a.access.close();a.finish();});result.putString("stream","PASS STAFF_GUIDE_CAPTURE\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e);finish(Activity.RESULT_CANCELED,result);}}
}
